package main

import (
 "crypto/rand"
 "encoding/hex"
 "encoding/json"
 "errors"
 "fmt"
 "math"
 "net/http"
 "os"
 "path/filepath"
 "sort"
 "strings"
 "sync"
 "time"
)

type User struct { ID string `json:"userId"`; Username string `json:"username"`; Password string `json:"password"`; Email string `json:"email,omitempty"`; FullName string `json:"fullName,omitempty"`; Phone string `json:"phone,omitempty"`; Roles []string `json:"roles"`; Qualifications []string `json:"qualifications"`; Certifications []map[string]any `json:"certifications"`; Active bool `json:"active"`; AssignedLocationID string `json:"assignedLocationId,omitempty"`; Available bool `json:"available"`; CapacityUnits int `json:"capacityUnits"` }
type Location struct { ID string `json:"locationId"`; Name string `json:"name"`; Coordinate map[string]float64 `json:"coordinate"`; CoverageKm float64 `json:"coverageKm"`; HandlingMinutes int `json:"handlingMinutes"`; Active bool `json:"active"`; Functions map[string]bool `json:"functions"`; Capacity int `json:"capacityUnits"`; CooledCapacity int `json:"cooledCapacityUnits"` }
type SampleType struct { ID string `json:"sampleTypeId"`; Name string `json:"name"`; Qualified bool `json:"qualifiedCollectorRequired"`; Qualification string `json:"requiredQualification"`; Container string `json:"containerType"`; Min float64 `json:"temperatureMinC"`; Max float64 `json:"temperatureMaxC"`; Incompatible []string `json:"incompatibleSampleTypes"`; Cooled bool `json:"requiresCooledRoute"`; Batching bool `json:"batchingAllowed"` }
type Sample struct { ID string `json:"sampleId"`; RequestID string `json:"requestId"`; RequesterID string `json:"requesterId"`; Origin map[string]float64 `json:"origin"`; OriginType string `json:"originType"`; RequestedAt string `json:"requestedAt"`; Deadline string `json:"deliveryDeadline"`; SampleTypeID string `json:"sampleTypeId"`; Container string `json:"containerType"`; Min float64 `json:"temperatureMinC"`; Max float64 `json:"temperatureMaxC"`; Incompatible []string `json:"incompatibleSampleTypes"`; Serviceability string `json:"serviceability"`; Status string `json:"status"`; Sealed bool `json:"sealed"`; HolderID string `json:"currentHolderId,omitempty"`; JourneyID string `json:"activeJourneyId,omitempty"`; TargetLabID string `json:"targetLaboratoryId,omitempty"`; Assignments []string `json:"activeAssignmentIds"`; Timeline []map[string]any `json:"timeline"`; Location map[string]float64 `json:"latestLocation,omitempty"`; LocationAt string `json:"locationRecordedAt,omitempty"`; Exception map[string]any `json:"exception,omitempty"` }
type Assignment struct { ID string `json:"assignmentId"`; SampleID string `json:"sampleId"`; WorkerID string `json:"workerId"`; Role string `json:"role"`; Status string `json:"status"`; OriginID string `json:"originId,omitempty"`; DestinationID string `json:"destinationId,omitempty"`; OfferedAt string `json:"offeredAt"` }
type Journey struct { ID string `json:"journeyId"`; PlanVersion int `json:"planVersion"`; RouteMode string `json:"routeMode"`; Status string `json:"status"`; SampleIDs []string `json:"sampleIds"`; OrderedStops []map[string]any `json:"orderedStops"`; Legs []map[string]any `json:"legs"`; Assignments []string `json:"assignmentIds"` }
type Handoff struct { ID string `json:"handoffId"`; SampleID string `json:"sampleId"`; SenderID string `json:"senderId"`; ReceiverID string `json:"receiverId"`; SenderConfirmed bool `json:"senderConfirmed"`; ReceiverConfirmed bool `json:"receiverConfirmed"`; Active bool `json:"active"` }
type Connection struct { ID string `json:"connectionId"`; From string `json:"fromLocationId"`; To string `json:"toLocationId"`; Travel int `json:"travelMinutes"`; Cost float64 `json:"costUnits"`; Cooled bool `json:"cooled"`; Active bool `json:"active"`; Capacity int `json:"capacityUnits"`; CooledCapacity int `json:"cooledCapacityUnits"` }
type Session struct { UserID string `json:"userId"`; Role string `json:"role"`; CreatedAt string `json:"createdAt"` }
type State struct { Users map[string]User `json:"users"`; Locations map[string]Location `json:"locations"`; Types map[string]SampleType `json:"types"`; Samples map[string]Sample `json:"samples"`; Assignments map[string]Assignment `json:"assignments"`; Journeys map[string]Journey `json:"journeys"`; Handoffs map[string]Handoff `json:"handoffs"`; Connections map[string]Connection `json:"connections"`; Sessions map[string]Session `json:"sessions"`; Audit []map[string]any `json:"audit"`; ServiceVersion int `json:"serviceVersion"`; NetworkRevision int `json:"networkRevision"` }
type App struct { mu sync.Mutex; state State; path string }

func id() string { b:=make([]byte,16); _,_=rand.Read(b); b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; return fmt.Sprintf("%s-%s-%s-%s-%s",hex.EncodeToString(b[:4]),hex.EncodeToString(b[4:6]),hex.EncodeToString(b[6:8]),hex.EncodeToString(b[8:10]),hex.EncodeToString(b[10:])) }
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func initial() State { s:=State{Users:map[string]User{},Locations:map[string]Location{},Types:map[string]SampleType{},Samples:map[string]Sample{},Assignments:map[string]Assignment{},Journeys:map[string]Journey{},Handoffs:map[string]Handoff{},Connections:map[string]Connection{},Sessions:map[string]Session{},Audit:[]map[string]any{},ServiceVersion:1}; for _,v:=range []struct{n,c string;lo,hi float64;cool,batch bool}{ {"Amber","standard",2,25,false,true},{"Indigo","standard",2,25,false,true},{"Frost","cooled",2,8,true,true},{"Pulse","priority",2,25,false,false} } { x:=SampleType{ID:id(),Name:v.n,Qualified:true,Qualification:v.n,Container:v.c,Min:v.lo,Max:v.hi,Cooled:v.cool,Batching:v.batch,Incompatible:[]string{}}; s.Types[x.ID]=x }; return s }
func load(path string) State { b,e:=os.ReadFile(path); if e!=nil{return initial()}; var s State; if json.Unmarshal(b,&s)!=nil{return initial()}; if s.Users==nil{return initial()}; return s }
func (a *App) save() { _=os.MkdirAll(filepath.Dir(a.path),0755); b,_:=json.MarshalIndent(a.state,"","  "); tmp:=a.path+".tmp"; _=os.WriteFile(tmp,b,0600); _=os.Rename(tmp,a.path) }
func (a *App) audit(u *User, action, entity, entityID, outcome string, changes any) { role:="system"; actor:="system"; if u!=nil { role=""; actor=u.ID }; a.state.Audit=append(a.state.Audit,map[string]any{"auditId":id(),"actorId":actor,"role":role,"action":action,"entityType":entity,"entityId":entityID,"occurredAt":now(),"success":outcome=="success","outcome":outcome,"changes":changes}) }
func write(w http.ResponseWriter,status int,v any) { w.Header().Set("Content-Type","application/json"); w.WriteHeader(status); _=json.NewEncoder(w).Encode(v) }
func fail(w http.ResponseWriter,status int,code,msg string) { write(w,status,map[string]string{"error":msg,"code":code}) }
func body(r *http.Request) (map[string]any,error) { var v map[string]any; d:=json.NewDecoder(r.Body); d.DisallowUnknownFields(); e:=d.Decode(&v); return v,e }
func str(v map[string]any,k string) string { x,_:=v[k].(string); return x }
func f64(v map[string]any,k string) float64 { x,_:=v[k].(float64); return x }
func boolv(v map[string]any,k string) bool { x,_:=v[k].(bool); return x }
func arr(v map[string]any,k string) []string { x,_:=v[k].([]any); o:=[]string{}; for _,q:=range x { if s,ok:=q.(string);ok{o=append(o,s)} }; return o }
func coord(v map[string]any,k string) map[string]float64 { x,_:=v[k].(map[string]any); return map[string]float64{"latitude":f64(x,"latitude"),"longitude":f64(x,"longitude")} }
func has(xs []string,x string) bool { for _,v:=range xs {if v==x{return true}}; return false }
func (a *App) user(r *http.Request) (*User, Session, bool) { h:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer "); se,ok:=a.state.Sessions[h]; if !ok{return nil,Session{},false}; u,ok:=a.state.Users[se.UserID]; return &u,se,ok&&u.Active }
func workerRole(role string) bool { return role=="collection_professional"||role=="delivery_partner"||role=="node_handler"||role=="laboratory_team" }
func allowed(role string, roles ...string) bool { for _,r:=range roles{if role==r||role=="administrator" {return true}}; return false }
func require(a *App,w http.ResponseWriter,r *http.Request,roles ...string)(*User,Session,bool){u,s,ok:=a.user(r); if !ok{fail(w,401,"unauthorized","Authentication is required");return nil,s,false}; if !allowed(s.Role,roles...){fail(w,403,"forbidden","Selected role is not permitted");return nil,s,false};return u,s,true}
func sampleView(s Sample) map[string]any { stale:=true; if s.LocationAt!="" { t,e:=time.Parse(time.RFC3339,s.LocationAt); stale=e!=nil||time.Since(t)>15*time.Minute }; return map[string]any{"sampleId":s.ID,"requestId":s.RequestID,"requesterId":s.RequesterID,"origin":s.Origin,"originType":s.OriginType,"requestedAt":s.RequestedAt,"deliveryDeadline":s.Deadline,"sampleTypeId":s.SampleTypeID,"containerType":s.Container,"temperatureMinC":s.Min,"temperatureMaxC":s.Max,"incompatibleSampleTypes":s.Incompatible,"serviceability":s.Serviceability,"activeAssignmentIds":s.Assignments,"state":map[string]any{"status":s.Status},"timeline":s.Timeline,"activeJourneyId":s.JourneyID,"targetLaboratoryId":s.TargetLabID,"latestLocation":s.Location,"locationRecordedAt":s.LocationAt,"locationStale":stale} }
