func distance(a,b map[string]float64)float64 { const r=6371; dlat:=(b["latitude"]-a["latitude"])*math.Pi/180; dlng:=(b["longitude"]-a["longitude"])*math.Pi/180; x:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(a["latitude"]*math.Pi/180)*math.Cos(b["latitude"]*math.Pi/180)*math.Sin(dlng/2)*math.Sin(dlng/2); return 2*r*math.Atan2(math.Sqrt(x),math.Sqrt(1-x)) }
func (a *App) service(origin map[string]float64,typeID,deadline string)(bool,string,string,string){ st,ok:=a.state.Types[typeID];if !ok{return false,"handling_rules_unsatisfiable","",""}; var points []Location; var labs []Location; for _,l:=range a.state.Locations {if l.Active&&l.Functions["collection_point"] {points=append(points,l)}; if l.Active&&l.Functions["laboratory"] {labs=append(labs,l)} }; covered:=false;for _,p:=range points {if distance(origin,p.Coordinate)<=5 {covered=true}};if !covered{return false,"outside_service_coverage","",""}; var lab *Location;for _,l:=range labs { if a.accepts(l.ID,typeID) {q:=l;lab=&q;break} };if lab==nil{return false,"no_accepting_laboratory","",""}; d,e:=time.Parse(time.RFC3339,deadline);if e==nil&&d.Before(time.Now().Add(20*time.Minute)){return false,"deadline_unreachable","",""}; if st.Cooled && lab.CooledCapacity<1{return false,"insufficient_capacity","",""}; return true,"serviceable",lab.ID,time.Now().Add(45*time.Minute).UTC().Format(time.RFC3339) }
func (a *App) accepts(lab,typeID string)bool { for _,e:=range a.state.Audit {if e["action"]=="laboratory_acceptance"&&e["entityId"]==lab {c,_:=e["changes"].(map[string]any);if c!=nil&&c["sampleTypeId"]==typeID {q,_:=c["accepts"].(bool);return q}} }; return false }
func (a *App) choose(role string, st SampleType, locationID string) string { var users []User; for _,u:=range a.state.Users {if u.Active&&u.Available&&has(u.Roles,role)&&(locationID==""||u.AssignedLocationID==locationID) && (!st.Qualified||role!="collection_professional"||has(u.Qualifications,st.Qualification)){users=append(users,u)} }; sort.Slice(users,func(i,j int)bool{return users[i].CapacityUnits>users[j].CapacityUnits});if len(users)>0{return users[0].ID};return "" }
