package main

import (
 "crypto/rand"
 "encoding/hex"
 "encoding/json"
 "errors"
 "fmt"
 "math"
 "net/http"
 "os"
 "path/filepath"
 "sort"
 "strings"
 "sync"
 "time"
)

type User struct { ID string `json:"userId"`; Username string `json:"username"`; Password string `json:"password"`; Email string `json:"email,omitempty"`; FullName string `json:"fullName,omitempty"`; Phone string `json:"phone,omitempty"`; Roles []string `json:"roles"`; Qualifications []string `json:"qualifications"`; Certifications []map[string]any `json:"certifications"`; Active bool `json:"active"`; AssignedLocationID string `json:"assignedLocationId,omitempty"`; Available bool `json:"available"`; CapacityUnits int `json:"capacityUnits"` }
type Location struct { ID string `json:"locationId"`; Name string `json:"name"`; Coordinate map[string]float64 `json:"coordinate"`; CoverageKm float64 `json:"coverageKm"`; HandlingMinutes int `json:"handlingMinutes"`; Active bool `json:"active"`; Functions map[string]bool `json:"functions"`; Capacity int `json:"capacityUnits"`; CooledCapacity int `json:"cooledCapacityUnits"` }
type SampleType struct { ID string `json:"sampleTypeId"`; Name string `json:"name"`; Qualified bool `json:"qualifiedCollectorRequired"`; Qualification string `json:"requiredQualification"`; Container string `json:"containerType"`; Min float64 `json:"temperatureMinC"`; Max float64 `json:"temperatureMaxC"`; Incompatible []string `json:"incompatibleSampleTypes"`; Cooled bool `json:"requiresCooledRoute"`; Batching bool `json:"batchingAllowed"` }
type Sample struct { ID string `json:"sampleId"`; RequestID string `json:"requestId"`; RequesterID string `json:"requesterId"`; Origin map[string]float64 `json:"origin"`; OriginType string `json:"originType"`; RequestedAt string `json:"requestedAt"`; Deadline string `json:"deliveryDeadline"`; SampleTypeID string `json:"sampleTypeId"`; Container string `json:"containerType"`; Min float64 `json:"temperatureMinC"`; Max float64 `json:"temperatureMaxC"`; Incompatible []string `json:"incompatibleSampleTypes"`; Serviceability string `json:"serviceability"`; Status string `json:"status"`; Sealed bool `json:"sealed"`; HolderID string `json:"currentHolderId,omitempty"`; JourneyID string `json:"activeJourneyId,omitempty"`; TargetLabID string `json:"targetLaboratoryId,omitempty"`; Assignments []string `json:"activeAssignmentIds"`; Timeline []map[string]any `json:"timeline"`; Location map[string]float64 `json:"latestLocation,omitempty"`; LocationAt string `json:"locationRecordedAt,omitempty"`; Exception map[string]any `json:"exception,omitempty"` }
type Assignment struct { ID string `json:"assignmentId"`; SampleID string `json:"sampleId"`; WorkerID string `json:"workerId"`; Role string `json:"role"`; Status string `json:"status"`; OriginID string `json:"originId,omitempty"`; DestinationID string `json:"destinationId,omitempty"`; OfferedAt string `json:"offeredAt"` }
type Journey struct { ID string `json:"journeyId"`; PlanVersion int `json:"planVersion"`; RouteMode string `json:"routeMode"`; Status string `json:"status"`; SampleIDs []string `json:"sampleIds"`; OrderedStops []map[string]any `json:"orderedStops"`; Legs []map[string]any `json:"legs"`; Assignments []string `json:"assignmentIds"` }
type Handoff struct { ID string `json:"handoffId"`; SampleID string `json:"sampleId"`; SenderID string `json:"senderId"`; ReceiverID string `json:"receiverId"`; SenderConfirmed bool `json:"senderConfirmed"`; ReceiverConfirmed bool `json:"receiverConfirmed"`; Active bool `json:"active"` }
