func (a *App) save() { _=os.MkdirAll(filepath.Dir(a.path),0755); b,_:=json.MarshalIndent(a.state,"","  "); tmp:=a.path+".tmp"; _=os.WriteFile(tmp,b,0600); _=os.Rename(tmp,a.path) }
func (a *App) audit(u *User, action, entity, entityID, outcome string, changes any) { role:="system"; actor:="system"; if u!=nil { role=""; actor=u.ID }; a.state.Audit=append(a.state.Audit,map[string]any{"auditId":id(),"actorId":actor,"role":role,"action":action,"entityType":entity,"entityId":entityID,"occurredAt":now(),"success":outcome=="success","outcome":outcome,"changes":changes}) }
func write(w http.ResponseWriter,status int,v any) { w.Header().Set("Content-Type","application/json"); w.WriteHeader(status); _=json.NewEncoder(w).Encode(v) }
func fail(w http.ResponseWriter,status int,code,msg string) { write(w,status,map[string]string{"error":msg,"code":code}) }
func body(r *http.Request) (map[string]any,error) { var v map[string]any; d:=json.NewDecoder(r.Body); d.DisallowUnknownFields(); e:=d.Decode(&v); return v,e }
func str(v map[string]any,k string) string { x,_:=v[k].(string); return x }
func f64(v map[string]any,k string) float64 { x,_:=v[k].(float64); return x }
func boolv(v map[string]any,k string) bool { x,_:=v[k].(bool); return x }
func arr(v map[string]any,k string) []string { x,_:=v[k].([]any); o:=[]string{}; for _,q:=range x { if s,ok:=q.(string);ok{o=append(o,s)} }; return o }
func coord(v map[string]any,k string) map[string]float64 { x,_:=v[k].(map[string]any); return map[string]float64{"latitude":f64(x,"latitude"),"longitude":f64(x,"longitude")} }
func has(xs []string,x string) bool { for _,v:=range xs {if v==x{return true}}; return false }
func (a *App) user(r *http.Request) (*User, Session, bool) { h:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer "); se,ok:=a.state.Sessions[h]; if !ok{return nil,Session{},false}; u,ok:=a.state.Users[se.UserID]; return &u,se,ok&&u.Active }
func workerRole(role string) bool { return role=="collection_professional"||role=="delivery_partner"||role=="node_handler"||role=="laboratory_team" }
func allowed(role string, roles ...string) bool { for _,r:=range roles{if role==r||role=="administrator" {return true}}; return false }
