func distance(a,b map[string]float64)float64 { const r=6371; dlat:=(b["latitude"]-a["latitude"])*math.Pi/180; dlng:=(b["longitude"]-a["longitude"])*math.Pi/180; x:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(a["latitude"]*math.Pi/180)*math.Cos(b["latitude"]*math.Pi/180)*math.Sin(dlng/2)*math.Sin(dlng/2); return 2*r*math.Atan2(math.Sqrt(x),math.Sqrt(1-x)) }
