func id() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 15) | 64
	b[8] = (b[8] & 63) | 128
	return fmt.Sprintf("%s-%s-%s-%s-%s", hex.EncodeToString(b[:4]), hex.EncodeToString(b[4:6]), hex.EncodeToString(b[6:8]), hex.EncodeToString(b[8:10]), hex.EncodeToString(b[10:]))
}
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func initial() State {
	s := State{Users: map[string]User{}, Locations: map[string]Location{}, Types: map[string]SampleType{}, Samples: map[string]Sample{}, Assignments: map[string]Assignment{}, Journeys: map[string]Journey{}, Handoffs: map[string]Handoff{}, Connections: map[string]Connection{}, Sessions: map[string]Session{}, Audit: []map[string]any{}, ServiceVersion: 1}
	for _, v := range []struct {
		n, c        string
		lo, hi      float64
		cool, batch bool
	}{{"Amber", "standard", 2, 25, false, true}, {"Indigo", "standard", 2, 25, false, true}, {"Frost", "cooled", 2, 8, true, true}, {"Pulse", "priority", 2, 25, false, false}} {
		x := SampleType{ID: id(), Name: v.n, Qualified: true, Qualification: v.n, Container: v.c, Min: v.lo, Max: v.hi, Cooled: v.cool, Batching: v.batch, Incompatible: []string{}}
		s.Types[x.ID] = x
	}
	return s
}
func load(path string) State {
	b, e := os.ReadFile(path)
	if e != nil {
		return initial()
	}
	var s State
	if json.Unmarshal(b, &s) != nil {
		return initial()
	}
	if s.Users == nil {
		return initial()
	}
	return s
}
func (a *App) save() {
	_ = os.MkdirAll(filepath.Dir(a.path), 0755)
	b, _ := json.MarshalIndent(a.state, "", "  ")
	tmp := a.path + ".tmp"
	_ = os.WriteFile(tmp, b, 0600)
	_ = os.Rename(tmp, a.path)
}
func (a *App) audit(u *User, action, entity, entityID, outcome string, changes any) {
	role := "system"
	actor := "system"
	if u != nil {
		role = ""
		actor = u.ID
	}
	a.state.Audit = append(a.state.Audit, map[string]any{"auditId": id(), "actorId": actor, "role": role, "action": action, "entityType": entity, "entityId": entityID, "occurredAt": now(), "success": outcome == "success", "outcome": outcome, "changes": changes})
}
func write(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
func fail(w http.ResponseWriter, status int, code, msg string) {
	write(w, status, map[string]string{"error": msg, "code": code})
}
func body(r *http.Request) (map[string]any, error) {
	var v map[string]any
	d := json.NewDecoder(r.Body)
	d.DisallowUnknownFields()
	e := d.Decode(&v)
	return v, e
}
func str(v map[string]any, k string) string  { x, _ := v[k].(string); return x }
func f64(v map[string]any, k string) float64 { x, _ := v[k].(float64); return x }
func boolv(v map[string]any, k string) bool  { x, _ := v[k].(bool); return x }
func arr(v map[string]any, k string) []string {
	x, _ := v[k].([]any)
	o := []string{}
	for _, q := range x {
		if s, ok := q.(string); ok {
			o = append(o, s)
		}
	}
	return o
}
func coord(v map[string]any, k string) map[string]float64 {
	x, _ := v[k].(map[string]any)
	return map[string]float64{"latitude": f64(x, "latitude"), "longitude": f64(x, "longitude")}
}
func has(xs []string, x string) bool {
	for _, v := range xs {
		if v == x {
			return true
		}
	}
	return false
}
func (a *App) user(r *http.Request) (*User, Session, bool) {
	h := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	se, ok := a.state.Sessions[h]
	if !ok {
		return nil, Session{}, false
	}
	u, ok := a.state.Users[se.UserID]
	return &u, se, ok && u.Active
}
func workerRole(role string) bool {
	return role == "collection_professional" || role == "delivery_partner" || role == "node_handler" || role == "laboratory_team"
}
func allowed(role string, roles ...string) bool {
	for _, r := range roles {
		if role == r || role == "administrator" {
			return true
		}
	}
	return false
}
func require(a *App, w http.ResponseWriter, r *http.Request, roles ...string) (*User, Session, bool) {
	u, s, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return nil, s, false
	}
	if !allowed(s.Role, roles...) {
		fail(w, 403, "forbidden", "Selected role is not permitted")
		return nil, s, false
	}
	return u, s, true
}
func sampleView(s Sample) map[string]any {
	stale := true
	if s.LocationAt != "" {
		t, e := time.Parse(time.RFC3339, s.LocationAt)
		stale = e != nil || time.Since(t) > 15*time.Minute
	}
	return map[string]any{"sampleId": s.ID, "requestId": s.RequestID, "requesterId": s.RequesterID, "origin": s.Origin, "originType": s.OriginType, "requestedAt": s.RequestedAt, "deliveryDeadline": s.Deadline, "sampleTypeId": s.SampleTypeID, "containerType": s.Container, "temperatureMinC": s.Min, "temperatureMaxC": s.Max, "incompatibleSampleTypes": s.Incompatible, "serviceability": s.Serviceability, "activeAssignmentIds": s.Assignments, "state": map[string]any{"status": s.Status}, "timeline": s.Timeline, "activeJourneyId": s.JourneyID, "targetLaboratoryId": s.TargetLabID, "latestLocation": s.Location, "locationRecordedAt": s.LocationAt, "locationStale": stale}
}
func timeline(s *Sample, status, detail string) {
	s.Status = status
	s.Timeline = append(s.Timeline, map[string]any{"eventId": id(), "status": status, "occurredAt": now(), "detail": detail})
}
func distance(a, b map[string]float64) float64 {
	const r = 6371
	dlat := (b["latitude"] - a["latitude"]) * math.Pi / 180
	dlng := (b["longitude"] - a["longitude"]) * math.Pi / 180
	x := math.Sin(dlat/2)*math.Sin(dlat/2) + math.Cos(a["latitude"]*math.Pi/180)*math.Cos(b["latitude"]*math.Pi/180)*math.Sin(dlng/2)*math.Sin(dlng/2)
	return 2 * r * math.Atan2(math.Sqrt(x), math.Sqrt(1-x))
}
func (a *App) service(origin map[string]float64, typeID, deadline string) (bool, string, string, string) {
	st, ok := a.state.Types[typeID]
	if !ok {
		return false, "handling_rules_unsatisfiable", "", ""
	}
	var points []Location
	var labs []Location
	for _, l := range a.state.Locations {
		if l.Active && l.Functions["collection_point"] {
			points = append(points, l)
		}
		if l.Active && l.Functions["laboratory"] {
			labs = append(labs, l)
		}
	}
	covered := false
	for _, p := range points {
		if distance(origin, p.Coordinate) <= 5 {
			covered = true
		}
	}
	if !covered {
		return false, "outside_service_coverage", "", ""
	}
	var lab *Location
	for _, l := range labs {
		if a.accepts(l.ID, typeID) {
			q := l
			lab = &q
			break
		}
	}
	if lab == nil {
		return false, "no_accepting_laboratory", "", ""
	}
	d, e := time.Parse(time.RFC3339, deadline)
	if e == nil && d.Before(time.Now().Add(20*time.Minute)) {
		return false, "deadline_unreachable", "", ""
	}
	if st.Cooled && lab.CooledCapacity < 1 {
		return false, "insufficient_capacity", "", ""
	}
	return true, "serviceable", lab.ID, time.Now().Add(45 * time.Minute).UTC().Format(time.RFC3339)
}
func (a *App) accepts(lab, typeID string) bool {
	for _, e := range a.state.Audit {
		if e["action"] == "laboratory_acceptance" && e["entityId"] == lab {
			c, _ := e["changes"].(map[string]any)
			if c != nil && c["sampleTypeId"] == typeID {
				q, _ := c["accepts"].(bool)
				return q
			}
		}
	}
	return false
}
func (a *App) choose(role string, st SampleType, locationID string) string {
	var users []User
	for _, u := range a.state.Users {
		if u.Active && u.Available && has(u.Roles, role) && (locationID == "" || u.AssignedLocationID == locationID) && (!st.Qualified || role != "collection_professional" || has(u.Qualifications, st.Qualification)) {
			users = append(users, u)
		}
	}
	sort.Slice(users, func(i, j int) bool { return users[i].CapacityUnits > users[j].CapacityUnits })
	if len(users) > 0 {
		return users[0].ID
	}
	return ""
}
func (a *App) newAssignment(s *Sample, role string, st SampleType, origin, dest string) string {
	wid := a.choose(role, st, dest)
	if wid == "" {
		return ""
	}
	z := Assignment{ID: id(), SampleID: s.ID, WorkerID: wid, Role: role, Status: "offered", OriginID: origin, DestinationID: dest, OfferedAt: now()}
	a.state.Assignments[z.ID] = z
	s.Assignments = append(s.Assignments, z.ID)
	return z.ID
}

func (a *App) serveHTTP(w http.ResponseWriter, r *http.Request) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if r.URL.Path == "/ready" {
		write(w, 200, map[string]string{"status": "ready"})
		return
	}
	if r.URL.Path == "/" || r.URL.Path == "/index.html" {
		http.ServeFile(w, r, "web/index.html")
		return
	}
	if !strings.HasPrefix(r.URL.Path, "/api/") {
		http.NotFound(w, r)
		return
	}
	if r.URL.Path == "/api/authenticate-user" {
		a.login(w, r)
		return
	}
	if r.URL.Path == "/api/events" {
		u, _, ok := a.user(r)
		if !ok {
			fail(w, 401, "unauthorized", "Authentication is required")
			return
		}
		_ = u
		write(w, 200, map[string]any{"data": map[string]any{"events": []any{}, "cursor": len(a.state.Audit)}})
		return
	}
	if r.URL.Path == "/api/ui/bootstrap" {
		a.bootstrap(w, r)
		return
	}
	if r.URL.Path == "/api/read-sample-state/" {
		fail(w, 404, "not_found", "Sample not found")
		return
	}
	if strings.HasPrefix(r.URL.Path, "/api/read-sample-state/") {
		a.readSample(w, r, strings.TrimPrefix(r.URL.Path, "/api/read-sample-state/"))
		return
	}
	if strings.HasPrefix(r.URL.Path, "/api/read-user/") {
		a.readUser(w, r, strings.TrimPrefix(r.URL.Path, "/api/read-user/"))
		return
	}
	if r.Method != "POST" {
		fail(w, 405, "method_not_allowed", "Use the documented method")
		return
	}
	v, e := body(r)
	if e != nil {
		fail(w, 400, "invalid_json", "Malformed or unsupported JSON")
		return
	}
	a.route(w, r, v)
}
func (a *App) login(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		fail(w, 405, "method_not_allowed", "Use POST")
		return
	}
	v, e := body(r)
	if e != nil || str(v, "username") == "" || str(v, "password") == "" {
		fail(w, 400, "invalid_json", "Username and password are required")
		return
	}
	for _, u := range a.state.Users {
		if u.Username == str(v, "username") && u.Password == str(v, "password") && u.Active {
			t := id()
			role := u.Roles[0]
			a.state.Sessions[t] = Session{u.ID, role, now()}
			a.audit(&u, "sign_in", "user", u.ID, "success", nil)
			a.save()
			write(w, 200, map[string]any{"data": map[string]any{"sessionToken": t, "userId": u.ID, "roles": u.Roles, "activeRole": role}})
			return
		}
	}
	fail(w, 401, "invalid_credentials", "Invalid username or password")
}
func (a *App) bootstrap(w http.ResponseWriter, r *http.Request) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	sam := []any{}
	for _, s := range a.state.Samples {
		if se.Role == "requester" && s.RequesterID != u.ID {
			continue
		}
		sam = append(sam, sampleView(s))
	}
	ops := map[string]any{"samples": []any{}, "workers": []any{}, "locations": []any{}, "connections": []any{}, "routes": []any{}, "handoffs": []any{}, "delays": []any{}, "exceptions": []any{}, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0}
	for _, s := range a.state.Samples {
		ops["samples"] = append(ops["samples"].([]any), map[string]any{"sampleId": s.ID, "status": s.Status, "locationStale": s.LocationAt == "", "currentHolderId": s.HolderID})
	}
	for _, l := range a.state.Locations {
		ops["locations"] = append(ops["locations"].([]any), l)
	}
	for _, c := range a.state.Connections {
		ops["connections"] = append(ops["connections"].([]any), c)
	}
	for _, u := range a.state.Users {
		if workerRole(se.Role) || se.Role == "dispatcher" || se.Role == "administrator" {
			ops["workers"] = append(ops["workers"].([]any), map[string]any{"workerId": u.ID, "fullName": u.FullName, "roles": u.Roles, "available": u.Available, "status": map[bool]string{true: "available", false: "unavailable"}[u.Available], "capacityUnits": u.CapacityUnits, "assignmentCount": 0, "locationStale": true})
		}
	}
	write(w, 200, map[string]any{"data": map[string]any{"user": map[string]any{"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": u.Roles, "activeRole": se.Role, "roleSelectionRequired": false}, "serverTime": now(), "requesterSamples": sam, "operations": ops}})
}
func (a *App) readSample(w http.ResponseWriter, r *http.Request, sid string) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	s, ok := a.state.Samples[sid]
	if !ok {
		fail(w, 404, "not_found", "Sample not found")
		return
	}
	if se.Role == "requester" && s.RequesterID != u.ID {
		fail(w, 403, "forbidden", "Sample belongs to another requester")
		return
	}
	write(w, 200, map[string]any{"data": sampleView(s)})
}
func (a *App) readUser(w http.ResponseWriter, r *http.Request, uid string) {
	_, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	if !allowed(se.Role, "administrator") {
		fail(w, 403, "forbidden", "Administrator role required")
		return
	}
	u, ok := a.state.Users[uid]
	if !ok {
		fail(w, 404, "not_found", "User not found")
		return
	}
	write(w, 200, map[string]any{"data": userView(u)})
}
func userView(u User) map[string]any {
	return map[string]any{"userId": u.ID, "username": u.Username, "email": u.Email, "fullName": u.FullName, "phone": u.Phone, "roles": u.Roles, "qualifications": u.Qualifications, "certifications": u.Certifications, "active": u.Active}
}
func (a *App) route(w http.ResponseWriter, r *http.Request, v map[string]any) {
	p := r.URL.Path
	if p == "/api/select-active-role" {
		u, se, ok := a.user(r)
		if !ok {
			fail(w, 401, "unauthorized", "Authentication is required")
			return
		}
		role := str(v, "role")
		if !has(u.Roles, role) {
			fail(w, 403, "forbidden", "Role is not assigned to this account")
			return
		}
		for t, x := range a.state.Sessions {
			if x.UserID == u.ID && t == strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ") {
				x.Role = role
				a.state.Sessions[t] = x
			}
		}
		a.audit(u, "select_role", "user", u.ID, "success", map[string]any{"role": role})
		a.save()
		write(w, 200, map[string]any{"data": map[string]any{"activeRole": role, "roles": u.Roles}})
		_ = se
		return
	}
	if p == "/api/check-serviceability" {
		_, se, ok := a.user(r)
		if !ok {
			fail(w, 401, "unauthorized", "Authentication is required")
			return
		}
		if !allowed(se.Role, "requester", "dispatcher") {
			fail(w, 403, "forbidden", "Requester or dispatcher role required")
			return
		}
		yes, reason, lab, eta := a.service(coord(v, "origin"), str(v, "sampleTypeId"), str(v, "deliveryDeadline"))
		o := map[string]any{"serviceable": yes, "reason": reason, "serviceabilityVersion": a.state.ServiceVersion}
		if yes {
			o["targetLaboratoryId"] = lab
			o["estimatedArrivalAt"] = eta
		}
		write(w, 200, map[string]any{"data": o})
		return
	}
	if p == "/api/create-collection-request" || p == "/api/ingest-presealed-sample" {
		a.createRequest(w, r, v, p == "/api/ingest-presealed-sample")
		return
	}
	if p == "/api/create-user" {
		a.createUser(w, r, v)
		return
	}
	if p == "/api/update-user-access" {
		a.updateUser(w, r, v)
		return
	}
	if p == "/api/create-sample-type" || p == "/api/update-sample-type" {
		a.typeAction(w, r, v, p)
		return
	}
	if p == "/api/create-location" || p == "/api/update-location" {
		a.locationAction(w, r, v, p)
		return
	}
	if p == "/api/create-connection" {
		a.connectionAction(w, r, v)
		return
	}
	if p == "/api/configure-laboratory-acceptance" {
		u, _, ok := require(a, w, r, "administrator")
		if !ok {
			return
		}
		a.audit(u, "laboratory_acceptance", "laboratory", str(v, "laboratoryId"), "success", map[string]any{"sampleTypeId": str(v, "sampleTypeId"), "accepts": boolv(v, "accepts")})
		a.save()
		write(w, 200, map[string]any{"data": map[string]any{"acceptanceId": id(), "accepts": boolv(v, "accepts")}})
		return
	}
	if p == "/api/configure-capacity" {
		a.capacity(w, r, v)
		return
	}
	if p == "/api/set-location-status" || p == "/api/set-location-function-status" || p == "/api/set-connection-status" || p == "/api/set-worker-availability" {
		a.statusAction(w, r, v, p)
		return
	}
	if p == "/api/accept-assignment" || p == "/api/decline-assignment" || p == "/api/update-assignment-progress" {
		a.assignmentAction(w, r, v, p)
		return
	}
	if p == "/api/collect-and-seal-sample" {
		a.seal(w, r, v)
		return
	}
	if p == "/api/record-worker-location" {
		a.workerLocation(w, r, v)
		return
	}
	if p == "/api/record-handling-checkpoint" {
		a.checkpoint(w, r, v)
		return
	}
	if p == "/api/confirm-handoff" {
		a.handoff(w, r, v)
		return
	}
	if p == "/api/confirm-laboratory-receipt" || p == "/api/record-laboratory-exception" {
		a.labAction(w, r, v, p)
		return
	}
	if p == "/api/read-sample-lifecycle" {
