		a.readUser(w, r, strings.TrimPrefix(r.URL.Path, "/api/read-user/"))
		return
	}
	if r.Method != "POST" {
		fail(w, 405, "method_not_allowed", "Use the documented method")
		return
	}
	v, e := body(r)
