	for _, s := range a.state.Samples {
		ops["samples"] = append(ops["samples"].([]any), map[string]any{"sampleId": s.ID, "status": s.Status, "locationStale": s.LocationAt == "", "currentHolderId": s.HolderID})
	}
	for _, l := range a.state.Locations {
		ops["locations"] = append(ops["locations"].([]any), l)
	}
	for _, c := range a.state.Connections {
		ops["connections"] = append(ops["connections"].([]any), c)
	}
	for _, u := range a.state.Users {
		if workerRole(se.Role) || se.Role == "dispatcher" || se.Role == "administrator" {
			ops["workers"] = append(ops["workers"].([]any), map[string]any{"workerId": u.ID, "fullName": u.FullName, "roles": u.Roles, "available": u.Available, "status": map[bool]string{true: "available", false: "unavailable"}[u.Available], "capacityUnits": u.CapacityUnits, "assignmentCount": 0, "locationStale": true})
		}
	}
	write(w, 200, map[string]any{"data": map[string]any{"user": map[string]any{"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": u.Roles, "activeRole": se.Role, "roleSelectionRequired": false}, "serverTime": now(), "requesterSamples": sam, "operations": ops}})
}
func (a *App) readSample(w http.ResponseWriter, r *http.Request, sid string) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	s, ok := a.state.Samples[sid]
	if !ok {
		fail(w, 404, "not_found", "Sample not found")
		return
	}
	if se.Role == "requester" && s.RequesterID != u.ID {
		fail(w, 403, "forbidden", "Sample belongs to another requester")
		return
	}
	write(w, 200, map[string]any{"data": sampleView(s)})
}
func (a *App) readUser(w http.ResponseWriter, r *http.Request, uid string) {
	_, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	if !allowed(se.Role, "administrator") {
		fail(w, 403, "forbidden", "Administrator role required")
		return
	}
