func (a *App) checkpoint(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u, _, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	s, yes := a.state.Samples[str(v, "sampleId")]
	if !yes {
		fail(w, 404, "not_found", "Sample not found")
		return
	}
	if s.HolderID != u.ID {
		fail(w, 403, "forbidden", "Only current holder can record checkpoint")
		return
	}
	good := str(v, "containerType") == s.Container && f64(v, "observedTemperatureC") >= s.Min && f64(v, "observedTemperatureC") <= s.Max
	if !good {
		s.Exception = map[string]any{"reason": "handling_noncompliance"}
		timeline(&s, "exception", "Handling checkpoint failed")
	}
	a.state.Samples[s.ID] = s
	a.save()
	write(w, 201, map[string]any{"data": map[string]any{"checkpointId": id(), "sampleId": s.ID, "compliant": good, "sampleStatus": s.Status}})
}
func (a *App) handoff(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u, _, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	h, yes := a.state.Handoffs[str(v, "handoffId")]
	if !yes {
		fail(w, 404, "not_found", "Handoff not found")
		return
	}
	side := str(v, "confirmationSide")
	if side == "sender" && h.SenderID == u.ID {
		h.SenderConfirmed = true
	} else if side == "receiver" && h.ReceiverID == u.ID {
		h.ReceiverConfirmed = true
	} else {
		fail(w, 403, "forbidden", "Not a handoff participant")
		return
	}
	status := "pending"
	holder := h.SenderID
	if h.SenderConfirmed && h.ReceiverConfirmed {
		h.Active = false
		status = "confirmed"
		holder = h.ReceiverID
		s := a.state.Samples[h.SampleID]
		s.HolderID = holder
		timeline(&s, "handoff_confirmed", "Custody transferred")
		a.state.Samples[s.ID] = s
	}
	a.state.Handoffs[h.ID] = h
	a.save()
	write(w, 201, map[string]any{"data": map[string]any{"handoffId": h.ID, "status": status, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed, "currentHolderId": holder}})
}
func (a *App) labAction(w http.ResponseWriter, r *http.Request, v map[string]any, p string) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	if se.Role != "laboratory_team" && !allowed(se.Role, "dispatcher") {
		fail(w, 403, "forbidden", "Laboratory role required")
		return
	}
	s, yes := a.state.Samples[str(v, "sampleId")]
	if !yes {
		fail(w, 404, "not_found", "Sample not found")
		return
	}
	lab := str(v, "laboratoryId")
	if p == "/api/confirm-laboratory-receipt" {
		timeline(&s, "received", "Laboratory receipt confirmed")
		s.HolderID = u.ID
		a.state.Samples[s.ID] = s
		a.save()
		write(w, 201, map[string]any{"data": map[string]any{"sampleId": s.ID, "laboratoryId": lab, "status": "received", "receivedAt": str(v, "receivedAt")}})
	} else {
		s.Exception = map[string]any{"reason": str(v, "reason")}
		timeline(&s, "exception", "Laboratory exception")
		a.state.Samples[s.ID] = s
		a.save()
		write(w, 201, map[string]any{"data": map[string]any{"exceptionId": id(), "sampleId": s.ID, "status": "exception", "reason": str(v, "reason")}})
	}
}
func (a *App) lifecycle(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	s, yes := a.state.Samples[str(v, "sampleId")]
	if !yes {
		fail(w, 404, "not_found", "Sample not found")
		return
	}
	if se.Role == "requester" && s.RequesterID != u.ID {
		fail(w, 403, "forbidden", "Sample belongs to another requester")
		return
	}
	write(w, 200, map[string]any{"data": map[string]any{"sampleId": s.ID, "status": s.Status, "sealed": s.Sealed, "completedLegIds": []any{}, "activeReplacementPlanIds": []any{}, "timeline": s.Timeline, "activeJourneyId": s.JourneyID, "currentHolderId": s.HolderID, "exception": s.Exception, "latestLocation": s.Location, "locationRecordedAt": s.LocationAt, "locationStale": s.LocationAt == ""}})
}
func (a *App) searchAudit(w http.ResponseWriter, r *http.Request, v map[string]any) {
	_, _, ok := require(a, w, r, "dispatcher")
	if !ok {
		return
	}
	out := []any{}
	q := strings.ToLower(str(v, "query"))
	for i := len(a.state.Audit) - 1; i >= 0; i-- {
		e := a.state.Audit[i]
		if q != "" && !strings.Contains(strings.ToLower(fmt.Sprint(e)), q) {
			continue
		}
		out = append(out, e)
	}
	lim := int(f64(v, "limit"))
	if lim == 0 {
		lim = 500
	}
	if len(out) > lim {
		out = out[:lim]
	}
	write(w, 200, map[string]any{"data": map[string]any{"entries": out, "total": len(out), "returned": len(out), "offset": 0, "limit": lim, "order": "newest_first", "hasMore": false}})
}
func (a *App) planAction(w http.ResponseWriter, r *http.Request, v map[string]any, p string) {
	u, _, ok := require(a, w, r, "dispatcher")
	if !ok {
		return
	}
	if p == "/api/report-disruption" {
		a.audit(u, "disruption", "resource", str(v, "resourceId"), "success", nil)
		a.save()
		write(w, 201, map[string]any{"data": map[string]any{"disruptionId": id(), "affectedSampleIds": []any{}, "replacementPlanIds": []any{}, "replanStatus": "not_required"}})
		return
	}
	j, yes := a.state.Journeys[str(v, "journeyId")]
	if !yes {
		fail(w, 404, "not_found", "Journey not found")
		return
	}
	if int(f64(v, "expectedPlanVersion")) != j.PlanVersion {
		fail(w, 409, "state_snapshot_changed", "Journey plan has changed")
		return
	}
	if p == "/api/cancel-journey" {
		j.Status = "cancelled"
		a.state.Journeys[j.ID] = j
		a.save()
		write(w, 201, map[string]any{"data": map[string]any{"journeyId": j.ID, "status": "cancelled", "sampleIds": j.SampleIDs}})
		return
	}
	j.PlanVersion++
	a.state.Journeys[j.ID] = j
	a.save()
	if p == "/api/reroute-journey" {
		write(w, 201, map[string]any{"data": map[string]any{"journeyId": j.ID, "replanStatus": "not_required"}})
	} else if p == "/api/split-journey" {
		write(w, 201, map[string]any{"data": map[string]any{"journey": j, "splitJourney": j}})
	} else {
		write(w, 201, map[string]any{"data": j})
	}
}
func main() {
	path := os.Getenv("LAB_DATA_PATH")
	if path == "" {
		path = ".lab-data/state.json"
	}
	a := &App{path: path, state: load(path)}
	if os.Getenv("LAB_INIT_ONLY") == "1" {
		a.save()
		return
	}
	if len(a.state.Users) == 0 {
		username := os.Getenv("ADMIN_USERNAME")
		password := os.Getenv("ADMIN_PASSWORD")
		if username == "" {
			username = "admin"
		}
		if password == "" {
			password = "admin123"
		}
		u := User{ID: id(), Username: username, Password: password, FullName: "Initial Administrator", Roles: []string{"administrator", "dispatcher"}, Qualifications: []string{}, Certifications: []map[string]any{}, Active: true, Available: true, CapacityUnits: 10}
		a.state.Users[u.ID] = u
		a.audit(&u, "bootstrap_admin", "user", u.ID, "success", nil)
		a.save()
	}
	http.HandleFunc("/", a.serveHTTP)
	fmt.Println("Lab logistics listening on 127.0.0.1:8080")
	if e := http.ListenAndServe("127.0.0.1:8080", nil); e != nil && !errors.Is(e, http.ErrServerClosed) {
		panic(e)
	}
}

