		return
	}
	if r.URL.Path == "/api/read-sample-state/" {
		fail(w, 404, "not_found", "Sample not found")
		return
	}
	if strings.HasPrefix(r.URL.Path, "/api/read-sample-state/") {
		a.readSample(w, r, strings.TrimPrefix(r.URL.Path, "/api/read-sample-state/"))
		return
	}
	if strings.HasPrefix(r.URL.Path, "/api/read-user/") {
		a.readUser(w, r, strings.TrimPrefix(r.URL.Path, "/api/read-user/"))
		return
	}
	if r.Method != "POST" {
		fail(w, 405, "method_not_allowed", "Use the documented method")
		return
	}
	v, e := body(r)
	if e != nil {
		fail(w, 400, "invalid_json", "Malformed or unsupported JSON")
		return
	}
	a.route(w, r, v)
}
func (a *App) login(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		fail(w, 405, "method_not_allowed", "Use POST")
		return
	}
	v, e := body(r)
	if e != nil || str(v, "username") == "" || str(v, "password") == "" {
		fail(w, 400, "invalid_json", "Username and password are required")
		return
	}
	for _, u := range a.state.Users {
		if u.Username == str(v, "username") && u.Password == str(v, "password") && u.Active {
			t := id()
			role := u.Roles[0]
			a.state.Sessions[t] = Session{u.ID, role, now()}
			a.audit(&u, "sign_in", "user", u.ID, "success", nil)
			a.save()
			write(w, 200, map[string]any{"data": map[string]any{"sessionToken": t, "userId": u.ID, "roles": u.Roles, "activeRole": role}})
			return
		}
	}
	fail(w, 401, "invalid_credentials", "Invalid username or password")
}
