func (a *App) route(w http.ResponseWriter, r *http.Request, v map[string]any) {
	p := r.URL.Path
	if p == "/api/select-active-role" {
		u, se, ok := a.user(r)
		if !ok {
			fail(w, 401, "unauthorized", "Authentication is required")
			return
		}
		role := str(v, "role")
		if !has(u.Roles, role) {
			fail(w, 403, "forbidden", "Role is not assigned to this account")
			return
		}
		for t, x := range a.state.Sessions {
			if x.UserID == u.ID && t == strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ") {
				x.Role = role
				a.state.Sessions[t] = x
			}
		}
		a.audit(u, "select_role", "user", u.ID, "success", map[string]any{"role": role})
		a.save()
		write(w, 200, map[string]any{"data": map[string]any{"activeRole": role, "roles": u.Roles}})
		_ = se
		return
	}
	if p == "/api/initiate-handoff" { a.initiateHandoff(w,r,v); return }
	if p == "/api/list-role-work" { a.listWork(w,r,v); return }
	if p == "/api/read-journey-plan" { a.readJourney(w,r,v); return }
	if p == "/api/read-operations-state" { a.operations(w,r); return }
	if p == "/api/merge-journeys" { a.mergeJourneys(w,r,v); return }
	if p == "/api/check-serviceability" {
		_, se, ok := a.user(r)
		if !ok {
			fail(w, 401, "unauthorized", "Authentication is required")
			return
		}
		if !allowed(se.Role, "requester", "dispatcher") {
			fail(w, 403, "forbidden", "Requester or dispatcher role required")
			return
		}
		yes, reason, lab, eta := a.service(coord(v, "origin"), str(v, "sampleTypeId"), str(v, "deliveryDeadline"))
		o := map[string]any{"serviceable": yes, "reason": reason, "serviceabilityVersion": a.state.ServiceVersion}
		if yes {
			o["targetLaboratoryId"] = lab
			o["estimatedArrivalAt"] = eta
		}
		write(w, 200, map[string]any{"data": o})
		return
	}
	if p == "/api/create-collection-request" || p == "/api/ingest-presealed-sample" {
		a.createRequest(w, r, v, p == "/api/ingest-presealed-sample")
		return
	}
	if p == "/api/create-user" {
		a.createUser(w, r, v)
		return
	}
	if p == "/api/update-user-access" {
		a.updateUser(w, r, v)
		return
	}
	if p == "/api/create-sample-type" || p == "/api/update-sample-type" {
		a.typeAction(w, r, v, p)
		return
	}
	if p == "/api/create-location" || p == "/api/update-location" {
		a.locationAction(w, r, v, p)
		return
	}
	if p == "/api/create-connection" {
		a.connectionAction(w, r, v)
		return
	}
	if p == "/api/configure-laboratory-acceptance" {
		u, _, ok := require(a, w, r, "administrator")
		if !ok {
			return
		}
		a.audit(u, "laboratory_acceptance", "laboratory", str(v, "laboratoryId"), "success", map[string]any{"sampleTypeId": str(v, "sampleTypeId"), "accepts": boolv(v, "accepts")})
		a.save()
		write(w, 200, map[string]any{"data": map[string]any{"acceptanceId": id(), "accepts": boolv(v, "accepts")}})
		return
	}
	if p == "/api/configure-capacity" {
		a.capacity(w, r, v)
		return
	}
	if p == "/api/set-location-status" || p == "/api/set-location-function-status" || p == "/api/set-connection-status" || p == "/api/set-worker-availability" {
		a.statusAction(w, r, v, p)
		return
	}
	if p == "/api/accept-assignment" || p == "/api/decline-assignment" || p == "/api/update-assignment-progress" {
		a.assignmentAction(w, r, v, p)
		return
	}
	if p == "/api/collect-and-seal-sample" {
		a.seal(w, r, v)
		return
	}
	if p == "/api/record-worker-location" {
		a.workerLocation(w, r, v)
		return
	}
	if p == "/api/record-handling-checkpoint" {
		a.checkpoint(w, r, v)
		return
	}
	if p == "/api/confirm-handoff" {
		a.handoff(w, r, v)
		return
	}
	if p == "/api/confirm-laboratory-receipt" || p == "/api/record-laboratory-exception" {
		a.labAction(w, r, v, p)
		return
	}
	if p == "/api/read-sample-lifecycle" {
		a.lifecycle(w, r, v)
		return
	}
	if p == "/api/read-serviceability-snapshot" {
		_, _, ok := require(a, w, r, "dispatcher")
		if !ok {
			return
		}
		write(w, 200, map[string]any{"data": map[string]any{"version": a.state.ServiceVersion, "status": "complete", "computedAt": now(), "networkRevision": a.state.NetworkRevision, "regions": []any{}, "activeCollectionPointCount": 0}})
		return
	}
	if p == "/api/search-audit-trail" {
		a.searchAudit(w, r, v)
		return
	}
	if p == "/api/cancel-journey" || p == "/api/reroute-journey" || p == "/api/edit-active-plan" || p == "/api/split-journey" || p == "/api/report-disruption" {
		a.planAction(w, r, v, p)
		return
	}
	fail(w, 404, "not_found", "Unknown API operation")
}
func (a *App) createRequest(w http.ResponseWriter, r *http.Request, v map[string]any, pre bool) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	if pre {
		if !workerRole(se.Role) {
			fail(w, 403, "forbidden", "A custody role is required")
			return
		}
		if str(v, "originType") == "home" {
			fail(w, 400, "invalid_origin", "Pre-sealed samples cannot originate at home")
			return
		}
	} else if !allowed(se.Role, "requester", "dispatcher") {
		fail(w, 403, "forbidden", "Requester role required")
		return
	}
	origin := coord(v, "origin")
	yes, reason, lab, _ := a.service(origin, str(v, "sampleTypeId"), str(v, "deliveryDeadline"))
	sid, rid := id(), id()
	typ := str(v, "originType")
	if typ == "" {
		typ = "home"
	}
	s := Sample{ID: sid, RequestID: rid, RequesterID: u.ID, Origin: origin, OriginType: typ, RequestedAt: str(v, "requestedAt"), Deadline: str(v, "deliveryDeadline"), SampleTypeID: str(v, "sampleTypeId"), Container: str(v, "containerType"), Min: f64(v, "temperatureMinC"), Max: f64(v, "temperatureMaxC"), Incompatible: arr(v, "incompatibleSampleTypes"), Serviceability: map[bool]string{true: "serviceable", false: "unserviceable"}[yes], Status: "requested", Location: origin}
	timeline(&s, "requested", "Request created")
	out := map[string]any{"requestId": rid, "sampleId": sid, "serviceability": s.Serviceability, "serviceabilityReason": reason, "activeAssignmentIds": []string{}, "earliestCollectionAt": str(v, "earliestCollectionAt"), "latestCollectionAt": str(v, "latestCollectionAt"), "alreadySealed": pre, "originType": typ}
	if out["earliestCollectionAt"] == "" {
		out["earliestCollectionAt"] = s.RequestedAt
	}
	if out["latestCollectionAt"] == "" {
		out["latestCollectionAt"] = s.RequestedAt
	}
	if yes {
		st := a.state.Types[s.SampleTypeID]
		s.TargetLabID = lab
		j := Journey{ID: id(), PlanVersion: 1, RouteMode: "direct", Status: "planned", SampleIDs: []string{sid}, OrderedStops: []map[string]any{{"locationId": lab, "order": 1}}, Legs: []map[string]any{}}
		s.JourneyID = j.ID
		role := "collection_professional"
		if pre {
			s.Sealed = true
			s.HolderID = u.ID
			timeline(&s, "sealed", "Pre-sealed sample registered")
			role = "delivery_partner"
		}
		aid := a.newAssignment(&s, role, st, "", lab)
		if aid != "" {
			j.Assignments = []string{aid}
			out["activeAssignmentIds"] = s.Assignments
		}
		a.state.Journeys[j.ID] = j
		out["journeyId"] = j.ID
		out["targetLaboratoryId"] = lab
	}
	a.state.Samples[sid] = s
	a.audit(u, "create_request", "sample", sid, "success", map[string]any{"serviceability": reason})
	a.save()
	write(w, 201, map[string]any{"data": out})
}
