func (a *App) createRequest(w http.ResponseWriter, r *http.Request, v map[string]any, pre bool) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	if pre {
		if !workerRole(se.Role) {
			fail(w, 403, "forbidden", "A custody role is required")
			return
		}
		if str(v, "originType") == "home" {
			fail(w, 400, "invalid_origin", "Pre-sealed samples cannot originate at home")
			return
		}
	} else if !allowed(se.Role, "requester", "dispatcher") {
		fail(w, 403, "forbidden", "Requester role required")
		return
	}
	origin := coord(v, "origin")
	yes, reason, lab, _ := a.service(origin, str(v, "sampleTypeId"), str(v, "deliveryDeadline"))
	sid, rid := id(), id()
	typ := str(v, "originType")
	if typ == "" {
		typ = "home"
	}
	s := Sample{ID: sid, RequestID: rid, RequesterID: u.ID, Origin: origin, OriginType: typ, RequestedAt: str(v, "requestedAt"), Deadline: str(v, "deliveryDeadline"), SampleTypeID: str(v, "sampleTypeId"), Container: str(v, "containerType"), Min: f64(v, "temperatureMinC"), Max: f64(v, "temperatureMaxC"), Incompatible: arr(v, "incompatibleSampleTypes"), Serviceability: map[bool]string{true: "serviceable", false: "unserviceable"}[yes], Status: "requested", Location: origin}
	timeline(&s, "requested", "Request created")
	out := map[string]any{"requestId": rid, "sampleId": sid, "serviceability": s.Serviceability, "serviceabilityReason": reason, "activeAssignmentIds": []string{}, "earliestCollectionAt": str(v, "earliestCollectionAt"), "latestCollectionAt": str(v, "latestCollectionAt"), "alreadySealed": pre, "originType": typ}
	if out["earliestCollectionAt"] == "" {
		out["earliestCollectionAt"] = s.RequestedAt
	}
	if out["latestCollectionAt"] == "" {
		out["latestCollectionAt"] = s.RequestedAt
	}
	if yes {
		st := a.state.Types[s.SampleTypeID]
		s.TargetLabID = lab
		j := Journey{ID: id(), PlanVersion: 1, RouteMode: "direct", Status: "planned", SampleIDs: []string{sid}, OrderedStops: []map[string]any{{"locationId": lab, "order": 1}}, Legs: []map[string]any{}}
		s.JourneyID = j.ID
		role := "collection_professional"
		if pre {
			s.Sealed = true
			s.HolderID = u.ID
			timeline(&s, "sealed", "Pre-sealed sample registered")
			role = "delivery_partner"
		}
		aid := a.newAssignment(&s, role, st, "", lab)
		if aid != "" {
			j.Assignments = []string{aid}
			out["activeAssignmentIds"] = s.Assignments
		}
		a.state.Journeys[j.ID] = j
		out["journeyId"] = j.ID
		out["targetLaboratoryId"] = lab
	}
	a.state.Samples[sid] = s
	a.audit(u, "create_request", "sample", sid, "success", map[string]any{"serviceability": reason})
	a.save()
	write(w, 201, map[string]any{"data": out})
}
