		stale = e != nil || time.Since(t) > 15*time.Minute
	}
	return map[string]any{"sampleId": s.ID, "requestId": s.RequestID, "requesterId": s.RequesterID, "origin": s.Origin, "originType": s.OriginType, "requestedAt": s.RequestedAt, "deliveryDeadline": s.Deadline, "sampleTypeId": s.SampleTypeID, "containerType": s.Container, "temperatureMinC": s.Min, "temperatureMaxC": s.Max, "incompatibleSampleTypes": s.Incompatible, "serviceability": s.Serviceability, "activeAssignmentIds": s.Assignments, "state": map[string]any{"status": s.Status}, "timeline": s.Timeline, "activeJourneyId": s.JourneyID, "targetLaboratoryId": s.TargetLabID, "latestLocation": s.Location, "locationRecordedAt": s.LocationAt, "locationStale": stale}
}
