		return
	}
	if p == "/api/record-worker-location" {
		a.workerLocation(w, r, v)
		return
	}
	if p == "/api/record-handling-checkpoint" {
		a.checkpoint(w, r, v)
		return
	}
	if p == "/api/confirm-handoff" {
		a.handoff(w, r, v)
		return
	}
