		a.workerLocation(w, r, v)
		return
	}
	if p == "/api/record-handling-checkpoint" {
		a.checkpoint(w, r, v)
		return
	}
	if p == "/api/confirm-handoff" {
		a.handoff(w, r, v)
		return
	}
	if p == "/api/confirm-laboratory-receipt" || p == "/api/record-laboratory-exception" {
		a.labAction(w, r, v, p)
		return
	}
	if p == "/api/read-sample-lifecycle" {
		a.lifecycle(w, r, v)
		return
	}
