func (a *App) searchAudit(w http.ResponseWriter, r *http.Request, v map[string]any) {
	_, _, ok := require(a, w, r, "dispatcher")
	if !ok {
		return
	}
	out := []any{}
	q := strings.ToLower(str(v, "query"))
	for i := len(a.state.Audit) - 1; i >= 0; i-- {
		e := a.state.Audit[i]
		if q != "" && !strings.Contains(strings.ToLower(fmt.Sprint(e)), q) {
			continue
		}
		out = append(out, e)
	}
	lim := int(f64(v, "limit"))
	if lim == 0 {
		lim = 500
	}
	if len(out) > lim {
		out = out[:lim]
	}
	write(w, 200, map[string]any{"data": map[string]any{"entries": out, "total": len(out), "returned": len(out), "offset": 0, "limit": lim, "order": "newest_first", "hasMore": false}})
