	j.PlanVersion++
	a.state.Journeys[j.ID] = j
	a.save()
	if p == "/api/reroute-journey" {
		write(w, 201, map[string]any{"data": map[string]any{"journeyId": j.ID, "replanStatus": "not_required"}})
