func (a *App) listWork(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	role := str(v, "role")
	if role == "" {
		role = se.Role
	}
	if role != se.Role {
		fail(w, 403, "forbidden", "Work is available only for the selected role")
		return
	}
	pending, inprogress, completed := []any{}, []any{}, []any{}
	for _, x := range a.state.Assignments {
		if x.WorkerID != u.ID || x.Role != role {
			continue
		}
		item := map[string]any{"assignmentId": x.ID, "sampleId": x.SampleID, "status": x.Status, "offeredAt": x.OfferedAt}
		if x.Status == "offered" {
			pending = append(pending, item)
		} else if x.Status == "completed" || x.Status == "delivered" {
			completed = append(completed, item)
		} else {
			inprogress = append(inprogress, item)
		}
	}
	write(w, 200, map[string]any{"data": map[string]any{"pending": pending, "inProgress": inprogress, "completed": completed}})
}
func (a *App) readJourney(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	j, yes := a.state.Journeys[str(v, "journeyId")]
	if !yes {
		fail(w, 404, "not_found", "Journey not found")
		return
	}
	if se.Role == "requester" {
		visible := false
		for _, sid := range j.SampleIDs {
			if a.state.Samples[sid].RequesterID == u.ID {
				visible = true
			}
		}
		if !visible {
			fail(w, 403, "forbidden", "Journey is not visible to this requester")
			return
		}
	}
	write(w, 200, map[string]any{"data": j})
}
func (a *App) operations(w http.ResponseWriter, r *http.Request) {
	_, se, ok := a.user(r)
	if !ok {
		fail(w, 401, "unauthorized", "Authentication is required")
		return
	}
	if !allowed(se.Role, "dispatcher") {
		fail(w, 403, "forbidden", "Dispatcher role required")
		return
	}
	samples, workers, locations, connections, exceptions := []any{}, []any{}, []any{}, []any{}, []any{}
	for _, s := range a.state.Samples {
		samples = append(samples, map[string]any{"sampleId": s.ID, "status": s.Status, "requestId": s.RequestID, "origin": s.Origin, "deliveryDeadline": s.Deadline, "currentHolderId": s.HolderID, "activeJourneyId": s.JourneyID, "latestLocation": s.Location, "locationRecordedAt": s.LocationAt, "locationStale": s.LocationAt == ""})
		if s.Exception != nil {
			exceptions = append(exceptions, s.Exception)
		}
	}
	for _, u := range a.state.Users {
		if workerRole(se.Role) || has(u.Roles, "delivery_partner") || has(u.Roles, "collection_professional") {
			workers = append(workers, map[string]any{"workerId": u.ID, "fullName": u.FullName, "roles": u.Roles, "available": u.Available, "status": map[bool]string{true: "available", false: "unavailable"}[u.Available], "capacityUnits": u.CapacityUnits, "assignmentCount": 0, "locationStale": true})
		}
	}
	for _, l := range a.state.Locations {
		locations = append(locations, l)
	}
	for _, c := range a.state.Connections {
		connections = append(connections, c)
	}
	write(w, 200, map[string]any{"data": map[string]any{"samples": samples, "workers": workers, "locations": locations, "connections": connections, "routes": []any{}, "handoffs": []any{}, "delays": []any{}, "exceptions": exceptions, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0}})
}
func (a *App) mergeJourneys(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u, _, ok := require(a, w, r, "dispatcher")
	if !ok {
		return
	}
	j, yes := a.state.Journeys[str(v, "targetJourneyId")]
	if !yes {
		fail(w, 404, "not_found", "Journey not found")
		return
	}
	if int(f64(v, "expectedPlanVersion")) != j.PlanVersion {
		fail(w, 409, "state_snapshot_changed", "Journey plan has changed")
		return
	}
	for _, sid := range arr(v, "sourceJourneyIds") {
		src, found := a.state.Journeys[sid]
		if !found {
			fail(w, 404, "not_found", "Source journey not found")
			return
		}
		for _, sampleID := range src.SampleIDs {
			j.SampleIDs = append(j.SampleIDs, sampleID)
			s := a.state.Samples[sampleID]
			s.JourneyID = j.ID
			a.state.Samples[sampleID] = s
		}
		src.Status = "merged"
		a.state.Journeys[src.ID] = src
	}
	j.RouteMode = "batched"
	j.PlanVersion++
	a.state.Journeys[j.ID] = j
	a.audit(u, "merge_journeys", "journey", j.ID, "success", nil)
	a.save()
	write(w, 201, map[string]any{"data": j})
}

func main() {
	path := os.Getenv("LAB_DATA_PATH")
	if path == "" {
		path = ".lab-data/state.json"
	}
	a := &App{path: path, state: load(path)}
	if os.Getenv("LAB_INIT_ONLY") == "1" {
		a.save()
		return
	}
	if len(a.state.Users) == 0 {
		username := os.Getenv("ADMIN_USERNAME")
		password := os.Getenv("ADMIN_PASSWORD")
		if username == "" {
			username = "admin"
		}
		if password == "" {
			password = "admin123"
		}
		u := User{ID: id(), Username: username, Password: password, FullName: "Initial Administrator", Roles: []string{"administrator", "dispatcher"}, Qualifications: []string{}, Certifications: []map[string]any{}, Active: true, Available: true, CapacityUnits: 10}
		a.state.Users[u.ID] = u
		a.audit(&u, "bootstrap_admin", "user", u.ID, "success", nil)
		a.save()
	}
	http.HandleFunc("/", a.serveHTTP)
	fmt.Println("Lab logistics listening on 127.0.0.1:8080")
	if e := http.ListenAndServe("127.0.0.1:8080", nil); e != nil && !errors.Is(e, http.ErrServerClosed) {
		panic(e)
	}
}

